SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(STORAGE_CREDITS) AS "ORG_STORAGE_CREDITS" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, "ACCOUNT_LOCATOR" AS ACCOUNT_LOCATOR, "REGION" AS REGION, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, "AVERAGE_BYTES" AS AVERAGE_BYTES, (CAST("CREDITS" AS DECIMAL(38, 9))) AS STORAGE_CREDITS FROM storage_daily_history) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "ORG_STORAGE_CREDITS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
